 "content": "def transform(grid):
    """Align the non-background motif next to the 2-divider and mark its far edge."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    dividers = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    if not dividers:
        return out
    divider = dividers[0]

    # Infer the background from non-divider cells; the less frequent non-2 color(s)
    # form the motif in the demonstrated tasks.
    from collections import Counter
    counts = Counter(v for row in grid for v in row if v != 2)
    if not counts:
        return out
    background = counts.most_common(1)[0][0]
    motif = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (2, background)]
    if not motif:
        return out

    min_c = min(c for _, c, _ in motif)
    max_c = max(c for _, c, _ in motif)
    if max_c < divider:
        shift = divider - 1 - max_c
        stripe = min_c + shift - 1
    elif min_c > divider:
        shift = divider + 1 - min_c
        stripe = max_c + shift + 1
    else:
        return out

    out = [[2 if grid[r][c] == 2 else background for c in range(w)] for r in range(h)]
    for r, c, color in motif:
        nc = c + shift
        if 0 <= nc < w:
            out[r][nc] = color
    if 0 <= stripe < w:
        for r in range(h):
            if out[r][stripe] != 2:
                out[r][stripe] = 8
    return out

if __name__ == '__main__':
